class Base {
public:
    virtual void foo();
    virtual ~Base();
};

class Derived : public Base {
public:
    void foo() override;
    ~Derived() override;
};

// Implementation notes:
// - Each class with virtual functions has a vtable pointer (vptr) as the first member.
// - The vtable is a static table of function pointers generated by the compiler.
// - During object construction, the vptr is initialized to point to the class's vtable.
// - For multiple inheritance, objects contain multiple subobjects, each with its own vptr.
// - Pointer adjustments are performed at runtime when casting between base and derived types.
// - Compiler may optimize vtable sharing or layout to reduce memory footprint.
// - Destructors are called in reverse order of construction, with vtable adjustments for proper cleanup.
